create extension if not exists pgcrypto;create table if not exists public.admin_users(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,email text,role text default 'admin',is_active boolean default true,created_at timestamptz default now());create table if not exists public.site_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value text,updated_at timestamptz default now());create table if not exists public.doctor_profile(id uuid primary key default gen_random_uuid(),full_name text,position text,description text,phone text,city text,experience text,education text,directions text,instagram text,facebook text,helsi text,photo_url text,updated_at timestamptz default now());create table if not exists public.services(id uuid primary key default gen_random_uuid(),slug text unique,title text not null,description text,price text,image_url text,published boolean default true,sort_order int default 0,created_at timestamptz default now());create table if not exists public.blog_posts(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,excerpt text,content text,image_url text,status text default 'draft',published boolean default false,created_at timestamptz default now());create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),name text not null,rating int default 5,text text not null,published boolean default false,created_at timestamptz default now());create table if not exists public.appointments(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,message text,status text default 'new',created_at timestamptz default now());alter table public.admin_users enable row level security;alter table public.site_settings enable row level security;alter table public.doctor_profile enable row level security;alter table public.services enable row level security;alter table public.blog_posts enable row level security;alter table public.reviews enable row level security;alter table public.appointments enable row level security;create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_users where user_id=auth.uid() and is_active=true);$$;drop policy if exists "admin read own" on public.admin_users;create policy "admin read own" on public.admin_users for select to authenticated using(user_id=auth.uid());drop policy if exists "public settings" on public.site_settings;create policy "public settings" on public.site_settings for select to anon,authenticated using(true);drop policy if exists "admin settings" on public.site_settings;create policy "admin settings" on public.site_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());drop policy if exists "public doctor" on public.doctor_profile;create policy "public doctor" on public.doctor_profile for select to anon,authenticated using(true);drop policy if exists "admin doctor" on public.doctor_profile;create policy "admin doctor" on public.doctor_profile for all to authenticated using(public.is_admin()) with check(public.is_admin());drop policy if exists "public services" on public.services;create policy "public services" on public.services for select to anon,authenticated using(published=true or public.is_admin());drop policy if exists "admin services" on public.services;create policy "admin services" on public.services for all to authenticated using(public.is_admin()) with check(public.is_admin());drop policy if exists "public blog" on public.blog_posts;create policy "public blog" on public.blog_posts for select to anon,authenticated using(published=true or public.is_admin());drop policy if exists "admin blog" on public.blog_posts;create policy "admin blog" on public.blog_posts for all to authenticated using(public.is_admin()) with check(public.is_admin());drop policy if exists "public reviews" on public.reviews;create policy "public reviews" on public.reviews for select to anon,authenticated using(published=true or public.is_admin());drop policy if exists "insert reviews" on public.reviews;create policy "insert reviews" on public.reviews for insert to anon,authenticated with check(published=false);drop policy if exists "admin reviews" on public.reviews;create policy "admin reviews" on public.reviews for all to authenticated using(public.is_admin()) with check(public.is_admin());drop policy if exists "insert appointments" on public.appointments;create policy "insert appointments" on public.appointments for insert to anon,authenticated with check(true);drop policy if exists "admin appointments" on public.appointments;create policy "admin appointments" on public.appointments for all to authenticated using(public.is_admin()) with check(public.is_admin());insert into public.site_settings(key,value) values('site_name','Маковецький Олександр'),('hero_kicker','Лікар-хірург · Київ'),('hero_title','Сучасна хірургія з турботою про пацієнта'),('hero_description','Консультація, діагностика, лікування та післяопераційний супровід.'),('hero_button','Записатися на консультацію'),('footer_text','Ваше здоровʼя — наша турбота.'),('instagram','https://instagram.com/makovetskiyoleksandr_'),('helsi','https://helsi.me/doctor/96f7bb02-d7d4-47e0-b57a-d07b6f9caea7'),('design_primary','#1769aa'),('design_bg','#f5f8fc'),('design_text','#182230'),('design_radius','18'),('design_button_radius','12'),('design_font','Inter,Arial,sans-serif') on conflict(key) do nothing;